#!/usr/bin/env python3
"""
generate_ontology_seed.py
=========================
Calls Claude Opus to generate comprehensive wine ontology seed data.
Outputs 4 SQL seed files to supabase/migrations/seed/.

Usage:
    ANTHROPIC_API_KEY=... python3 scripts/generate_ontology_seed.py
    CLAUDE_API_KEY=... python3 scripts/generate_ontology_seed.py
    python3 scripts/generate_ontology_seed.py --fallback   # skip API, use embedded data

Cost estimate: ~$3-8 total (claude-opus-4-5, 12 API calls, ~8192 output tokens each)
"""
import os
import sys
import re
import time
import pathlib
import argparse

SEED_DIR = pathlib.Path("supabase/migrations/seed")
SEED_DIR.mkdir(parents=True, exist_ok=True)

# Model preference list — first available wins
MODELS_TO_TRY = [
    "claude-opus-4-5-20251001",
    "claude-opus-4-5",
    "claude-3-opus-20240229",
]

SOURCE_REF = "claude-opus-seed-v1"

# ---------------------------------------------------------------------------
# API helpers
# ---------------------------------------------------------------------------

def get_api_key() -> str | None:
    return (
        os.environ.get("ANTHROPIC_API_KEY")
        or os.environ.get("CLAUDE_API_KEY")
    )


def detect_model(client) -> str | None:
    """Return first working model name."""
    for model in MODELS_TO_TRY:
        try:
            client.messages.create(
                model=model, max_tokens=10,
                messages=[{"role": "user", "content": "ping"}],
            )
            print(f"  [model] {model} ✓", flush=True)
            return model
        except Exception as e:
            err = str(e).lower()
            if any(x in err for x in ("not_found", "invalid_model", "404", "model_not_found")):
                print(f"  [model] {model} not available, trying next...", flush=True)
            else:
                raise
    return None


def call_claude(client, model: str, prompt: str, max_tokens: int = 8192) -> str:
    """Call Claude and return text content."""
    msg = client.messages.create(
        model=model, max_tokens=max_tokens,
        messages=[{"role": "user", "content": prompt}],
    )
    return msg.content[0].text


def extract_inserts(text: str, table: str) -> list[str]:
    """Extract valid INSERT lines starting with INSERT INTO <table>."""
    lines = []
    for raw in text.strip().split("\n"):
        line = raw.strip()
        # Normalise: lowercase prefix check
        if re.match(rf"INSERT\s+INTO\s+{re.escape(table)}\s*\(", line, re.IGNORECASE):
            # Ensure ends with semicolon
            if not line.endswith(";"):
                line += ";"
            # Fix canonical_name: replace JSON-style aliases with PG TEXT[] style
            line = fix_aliases_format(line)
            lines.append(line)
    return lines


def fix_aliases_format(sql: str) -> str:
    """Convert JSON-array aliases like '["foo","bar"]' to PG TEXT[] '{foo,bar}'."""
    def _json_to_pg(match):
        inner = match.group(1)
        # Extract quoted strings
        items = re.findall(r'"([^"]+)"', inner)
        if not items:
            return "'{}'"
        escaped = [i.replace("'", "''") for i in items]
        return "'{" + ",".join(escaped) + "}'"
    return re.sub(r"'\[([^\]]*)\]'", _json_to_pg, sql)


def write_seed_file(filename: str, header: str, sql_lines: list[str]) -> int:
    """Write seed SQL file. Returns row count."""
    path = SEED_DIR / filename
    content = (
        f"-- {header}\n"
        f"-- Generated by scripts/generate_ontology_seed.py\n"
        f"-- Source: {SOURCE_REF}\n\n"
        + "\n".join(sql_lines)
        + "\n"
    )
    path.write_text(content)
    return len(sql_lines)


