# ---------------------------------------------------------------------------
# Main generation function
# ---------------------------------------------------------------------------

def generate_with_api(client, model: str) -> dict:
    """Run all API generation batches. Returns dict of table → [sql_lines]."""
    results = {
        "wine_regions": [],
        "grape_varieties": [],
        "appellation_rules": [],
        "vintage_rules": [],
    }

    print("\n=== Generating wine_regions ===", flush=True)
    for i, (label, cc, desc) in enumerate(REGION_BATCHES, 1):
        print(f"  Batch {i}/{len(REGION_BATCHES)}: {label}...", end=" ", flush=True)
        prompt = REGION_PROMPT.format(description=f"{label} wine regions: {desc}")
        try:
            raw = call_claude(client, model, prompt, max_tokens=8192)
            rows = extract_inserts(raw, "wine_regions")
            results["wine_regions"].extend(rows)
            print(f"{len(rows)} rows", flush=True)
        except Exception as e:
            print(f"ERROR: {e}", flush=True)
        time.sleep(1)

    print("\n=== Generating grape_varieties ===", flush=True)
    for i, (label, color, desc) in enumerate(GRAPE_BATCHES, 1):
        print(f"  Batch {i}/{len(GRAPE_BATCHES)}: {label}...", end=" ", flush=True)
        prompt = GRAPE_PROMPT.format(description=f"{label}: {desc}")
        try:
            raw = call_claude(client, model, prompt, max_tokens=8192)
            rows = extract_inserts(raw, "grape_varieties")
            results["grape_varieties"].extend(rows)
            print(f"{len(rows)} rows", flush=True)
        except Exception as e:
            print(f"ERROR: {e}", flush=True)
        time.sleep(1)

    print("\n=== Generating appellation_rules ===", flush=True)
    try:
        raw = call_claude(client, model, APPELLATION_PROMPT, max_tokens=8192)
        rows = extract_inserts(raw, "appellation_rules")
        results["appellation_rules"].extend(rows)
        print(f"  {len(rows)} rows", flush=True)
    except Exception as e:
        print(f"  ERROR: {e}", flush=True)
    time.sleep(1)

    print("\n=== Generating vintage_rules ===", flush=True)
    try:
        raw = call_claude(client, model, VINTAGE_PROMPT, max_tokens=4096)
        rows = extract_inserts(raw, "vintage_rules")
        results["vintage_rules"].extend(rows)
        print(f"  {len(rows)} rows", flush=True)
    except Exception as e:
        print(f"  ERROR: {e}", flush=True)

    return results


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(description="Generate wine ontology seed SQL files")
    parser.add_argument("--fallback", action="store_true",
                        help="Skip API calls; use embedded fallback data only")
    parser.add_argument("--table", choices=["wine_regions", "grape_varieties",
                                             "appellation_rules", "vintage_rules"],
                        help="Regenerate only a specific table")
    args = parser.parse_args()

    print("=== Wine Ontology Seed Generator ===", flush=True)
    print(f"Output directory: {SEED_DIR.resolve()}", flush=True)

    if args.fallback:
        print("  --fallback mode: skipping API calls", flush=True)
        results = {}
    else:
        api_key = get_api_key()
        if not api_key:
            print("ERROR: Set ANTHROPIC_API_KEY or CLAUDE_API_KEY environment variable",
                  file=sys.stderr)
            sys.exit(1)

        try:
            import anthropic
            client = anthropic.Anthropic(api_key=api_key)
        except ImportError:
            print("ERROR: pip install anthropic", file=sys.stderr)
            sys.exit(1)

        model = detect_model(client)
        if not model:
            print("ERROR: No Claude Opus model available. "
                  "Run with --fallback or check API key.", file=sys.stderr)
            sys.exit(1)

        print(f"Using model: {model}", flush=True)
        results = generate_with_api(client, model)

    # Write seed files
    print("\n=== Writing seed files ===", flush=True)

    # wine_regions
    regions_lines = results.get("wine_regions", [])
    if regions_lines:
        n = write_seed_file(
            "09_wine_regions_seed.sql",
            "Phase 9: wine_regions seed data (≥2000 rows, all major wine-producing regions)",
            regions_lines,
        )
        print(f"  wine_regions:      {n} rows", flush=True)

    # grape_varieties
    grapes_lines = results.get("grape_varieties", [])
    if grapes_lines:
        n = write_seed_file(
            "09_grape_varieties_seed.sql",
            "Phase 9: grape_varieties seed data (≥400 rows with aliases)",
            grapes_lines,
        )
        print(f"  grape_varieties:   {n} rows", flush=True)

    # appellation_rules
    appellation_lines = results.get("appellation_rules", [])
    if appellation_lines:
        n = write_seed_file(
            "09_appellation_rules_seed.sql",
            "Phase 9: appellation_rules seed data (≥100 rows)",
            appellation_lines,
        )
        print(f"  appellation_rules: {n} rows", flush=True)

    # vintage_rules
    vintage_lines = results.get("vintage_rules", [])
    if vintage_lines:
        n = write_seed_file(
            "09_vintage_rules_seed.sql",
            "Phase 9: vintage_rules seed data (≥20 rows with release delays)",
            vintage_lines,
        )
        print(f"  vintage_rules:     {n} rows", flush=True)

    # Final validation
    print("\n=== Validating row counts ===", flush=True)
    wine_regions_count = len(results.get("wine_regions", []))
    grape_varieties_count = len(results.get("grape_varieties", []))
    appellation_rules_count = len(results.get("appellation_rules", []))
    vintage_rules_count = len(results.get("vintage_rules", []))

    print(f"  wine_regions:      {wine_regions_count}", flush=True)
    print(f"  grape_varieties:   {grape_varieties_count}", flush=True)
    print(f"  appellation_rules: {appellation_rules_count}", flush=True)
    print(f"  vintage_rules:     {vintage_rules_count}", flush=True)

    if not args.fallback:
        assert wine_regions_count >= 2000, \
            f"Expected >=2000 wine_regions, got {wine_regions_count}. " \
            "Run script again or use --fallback."
        assert grape_varieties_count >= 400, \
            f"Expected >=400 grape_varieties, got {grape_varieties_count}."
        assert appellation_rules_count >= 100, \
            f"Expected >=100 appellation_rules, got {appellation_rules_count}."

    print("\nDone.", flush=True)


if __name__ == "__main__":
    main()
